from dataclasses import dataclass


@dataclass
class Reshape:
    shape: list[int]

@dataclass
class Permute:
    order: list[int]

@dataclass
class Pad:
    pads: list[int]  # left and right for each axis: [l0, r0, l1, r1, ...]

@dataclass
class Expand:
    shape: list[int]

@dataclass
class Reduce:
    m: int  # drops the first m axes

Op = Reshape | Permute | Pad | Expand | Reduce


def shape_after(shape: list[int], ops: list[Op]) -> list[int]:
    """The shape after applying ops in order. The inputs are always valid."""
    return shape
